<?php require_once __DIR__.'/../includes/config.php'; require_once __DIR__.'/../includes/database.php'; require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/csrf.php'; require_once __DIR__.'/../includes/functions.php'; if ($_SERVER['REQUEST_METHOD']!=='POST') redirect('login.php'); verify_csrf(); $email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL); $stmt=db()->prepare('SELECT id,name,email,password,role FROM users WHERE email=? LIMIT 1'); $stmt->execute([$email]); $u=$stmt->fetch(); if(!$u || !password_verify($_POST['password']??'',$u['password'])) { flash('error','Correo o contraseña incorrectos.'); redirect('login.php'); } login_user($u); redirect('dashboard.php');
